'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s||'').replace(/[\s，。！？、；：,.!?…“”「」《》\-—·()（）]/g,'').toLowerCase();
const uuid=()=>crypto.randomUUID();const num=n=>new Intl.NumberFormat('ru-RU').format(n);
const selectedTopics=new Set();
let corpus={},data=[],raw=[],sheets=[],view='cards',query='',topic='',level='',status='',sourceFilter='',quality='',page=0,onlyWork=true,ready=false;
let edits={},deleted=[],completed=[],history=[],extraRaw=[],dailyTraining={},editing=null,rawId=null,reviewQueue=[],reviewAt=0,revealed=false,reviewDone=0;
let quizTopic='',quizStarted=false,quizSelection=[];let quizMode='Площадка',quiz=[],quizAt=0,score=0,answered=false,wrong=[],quizPicked=-1;let storageError=false;
const ACTIVITY_KEY='chinese-practice-counts-v1';
function readActivity(){try{return JSON.parse(localStorage.getItem(ACTIVITY_KEY)||'{}')}catch{return {}}}
function mergeActivity(incoming){const current=readActivity();for(const [key,v]of Object.entries(incoming)){const old=current[key]||{};current[key]={cards:Math.max(old.cards||0,v.cards||0),tests:Math.max(old.tests||0,v.tests||0)}}try{localStorage.setItem(ACTIVITY_KEY,JSON.stringify(current))}catch{}}
function recordPractice(type){const key=dailyToday()+':'+activeDevice()+':'+activeTab(),all=readActivity();all[key]??={cards:0,tests:0};all[key][type]++;mergeActivity(all);persist()}
function practiceToday(){const all=readActivity(),day=dailyToday(),sum={cards:0,tests:0};for(const [key,v]of Object.entries(all))if(key.startsWith(day+':')){sum.cards+=v.cards||0;sum.tests+=v.tests||0}return sum}
function rankSidebar(v){const side=document.querySelector('aside');if(!side)return;const buttons=[...side.querySelectorAll(':scope > [data-nav]')],counts=safeObject('chinese-sidebar-frequency-v1');if(v&&v!=='home')counts[v]=(Number(counts[v])||0)+1;const positions=new Map(buttons.map((b,i)=>[b.dataset.nav,i]));buttons.sort((a,b)=>a.dataset.nav==='home'?-1:b.dataset.nav==='home'?1:(Number(counts[b.dataset.nav])||0)-(Number(counts[a.dataset.nav])||0)||positions.get(a.dataset.nav)-positions.get(b.dataset.nav));for(const button of buttons)side.insertBefore(button,side.querySelector(':scope > small'));try{localStorage.setItem('chinese-sidebar-frequency-v1',JSON.stringify(counts));localStorage.setItem('chinese-sidebar-order',JSON.stringify(buttons.map(b=>b.dataset.nav)))}catch{}}

const STORAGE='chinese-workbench-v2';let saved=null;try{saved=JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{}
if(saved){edits=saved.edits||{};deleted=saved.deleted||[];completed=saved.completed||[];history=saved.history||[];extraRaw=saved.extraRaw||[];dailyTraining=saved.training||{}}
const WORK_TOPICS=['SIMOPS','Монтаж оборудования','Трубопроводы и арматура','Сварка и резка','Подъёмные работы','Металлоконструкции и опоры','Охрана труда и допуски','Изоляция и LOTO','Электрика и КИП','Пусконаладка и испытания','Приёмка и качество','Логистика и поставки','Материалы и инструмент','Документация и чертежи','Графики и сроки','Координация и интерфейсы','Совещания и коммуникация','Риски и изменения','Нефтегаз и СПГ','Гражданские работы','Переговоры и договоры','Технологические процессы','Управление проектом','Профессии и обязанности','Площадка · общие термины'];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const dbReady=new Promise(resolve=>{if(typeof indexedDB==='undefined'){resolve(null);return}let r;try{r=indexedDB.open('my-chinese-workbench',1)}catch{resolve(null);return}r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('settings'))r.result.createObjectStore('settings')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);r.onblocked=()=>resolve(null)});
async function readDB(){const db=await dbReady;if(!db)return null;return new Promise(resolve=>{try{const r=db.transaction('settings').objectStore('settings').get('state');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null)}catch{resolve(null)}})}
function payload(){return {version:2,edits,deleted,completed,history:history.slice(-500),extraRaw,training:dailyTraining,writing:Object.fromEntries(writingRecords),activity:readActivity(),activeTime:readActiveTimeShards()}}
function persist(){const snapshot=structuredClone(payload());window.ChineseCloud?.schedule(snapshot);dbReady.then(db=>{if(db){try{const tx=db.transaction('settings','readwrite');tx.objectStore('settings').put(snapshot,'state');tx.oncomplete=()=>{storageError=false};tx.onerror=()=>fallbackSave(snapshot);return}catch{}}fallbackSave(snapshot)});return true}
function fallbackSave(snapshot){try{localStorage.setItem(STORAGE,JSON.stringify(snapshot));storageError=false}catch{storageError=true;toast('Не удалось сохранить в браузере. Сразу экспортируй резервную копию.')}}

function standard(d){d={...d};d.tags=Array.isArray(d.tags)?d.tags.filter(Boolean):[d.topic||'Общая лексика'];d.topic=d.topic||d.tags[0];if(!d.tags.includes(d.topic))d.tags.unshift(d.topic);d.work=d.work??(d.level==='Технический');if(d.level==='Технический')d.level='Уровень не указан';d.sources=Array.isArray(d.sources)?d.sources:[];d.examples=Array.isArray(d.examples)?d.examples:(d.ex&&d.ep&&d.er?[{zh:d.ex,py:d.ep,ru:d.er}]:[]);d.state=d.state||'Новое';d.complete=!!(d.zh&&d.py&&d.ru);return d}
function priority(d){return (d.complete?10:0)+(d.sources.some(s=>s.sheet==='ЗАВОД')?20:0)+(d.quality==='Проверено вручную'?5:0)+(/吊装|安装|焊接|管道|法兰|阀门|电缆|钢结构|支架|找正|作业|隔离/.test(d.zh)?30:0)+(d.examples.length?5:0)}
function rebuild(){reviewPhraseIndex=null;let by=new Map((corpus.clean||[]).map(d=>[d.id,standard(d)]));for(const [oldId,d]of Object.entries(edits)){if(corpus.archived?.some(x=>x.id===oldId)&&d.quality!=='Проверено вручную')continue;const id=corpus.aliases?.[oldId]||oldId;const base=by.get(id);if(base&&d.quality!=='Проверено вручную'&&!oldId.startsWith('user-'))by.set(id,standard({...base,state:d.state||base.state,due:d.due,favorite:!!d.favorite,viewedAt:d.viewedAt,memoryAt:d.memoryAt,favoriteAt:d.favoriteAt}));else by.set(id,standard({...d,id,tags:base?.tags?.includes('Оборудование')?[...new Set([...(d.tags||[]),'Оборудование'])]:d.tags}))}data=[...by.values()].filter(d=>!deleted.includes(d.id)).sort((a,b)=>priority(b)-priority(a));raw=[...(corpus.raw||[]),...extraRaw];sheets=corpus.sheets||[];for(const d of data)d._search=fold([d.zh,d.py,d.ru,d.tags.join(' '),d.meanings?.join(' ')||'',d.examples.map(e=>[e.zh,e.py,e.ru].join(' ')).join(' '),d.source].join(' '));}
function fold(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'')}
function update(d){d=standard(d);edits[d.id]=d;let i=data.findIndex(x=>x.id===d.id);if(i>=0)data[i]=d;else data.push(d);d._search=fold([d.zh,d.py,d.ru,d.tags.join(' '),d.examples.map(e=>[e.zh,e.py,e.ru].join(' ')).join(' '),d.source].join(' '));persist()}
function filtered(){const q=fold(query.trim());return rankedMatches(data.filter(d=>(view!=='equipment'||d.tags.includes('Оборудование'))&&(view!=='slang'||!!d.slangGroup)&&(view!=='remembered'||d.state==='Изучено')&&(view!=='idioms'||d.tags.includes('Идиомы')||d.tags.includes('Деловые выражения'))&&(view!=='repeat'||d.state==='Повторить')&&(view!=='favorites'||d.favorite)&&((view!=='tech'&&!onlyWork)||d.work)&&(!q||d._search.includes(q))&&(!topic||d.tags.includes(topic))&&(!selectedTopics.size||d.tags.some(t=>selectedTopics.has(t)))&&(!level||d.level===level)&&(!status||d.state===status)&&(!sourceFilter||d.sources.some(s=>s.sheet===sourceFilter)||d.source.startsWith(sourceFilter))&&(!quality||(quality==='complete'?d.complete:quality==='missing'?!d.complete:quality==='auto'?d.pyOrigin==='Автоматически':d.quality===quality))),q)}
function opts(arr,v){return arr.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function allTopics(work=false){if(view==='slang')return ['Живые разговорные фразы','Интернет-сленг','Грубые и резкие'];return [...new Set(data.filter(d=>!work||d.work).flatMap(d=>d.tags))].sort((a,b)=>a.localeCompare(b,'ru'))}
function resetFilters(){selectedTopics.clear();query=topic=level=status=sourceFilter=quality='';page=0;onlyWork=false;reviewQueue=[];reviewAt=0;revealed=false}
function nav(v){rankSidebar(v);if(['repeat','remembered','favorites'].includes(v))shuffledOrders.delete(v);view=v;resetFilters();onlyWork=v==='cards'||v==='home';if(v==='import')loadSources();document.querySelector('#mobileMenu')?.close();render();window.scrollTo(0,0)}
function filters(){return `<div class="bar"><input id="search" aria-label="Поиск" placeholder="Иероглифы, пиньинь, перевод или тема…" value="${esc(query)}"><select id="topic" aria-label="Тема"><option value="">Все темы</option>${opts(allTopics(view==='tech'||onlyWork),topic)}</select>${view==='base'?`<button id="equipmentFilter" aria-pressed="${topic==='Оборудование'}">⚙ Оборудование</button>`:''}<button id="add" class="primary">＋ Добавить</button></div><details class="advancedFilters" ${window.innerWidth>700?'open':''}><summary>Дополнительные фильтры</summary><div class="bar" style="margin-top:-10px"><select id="level" aria-label="Уровень"><option value="">Все уровни</option>${opts(['HSK 1','HSK 2','HSK 3','HSK 4','HSK 5','HSK 6','Уровень не указан'],level)}</select><select id="status" aria-label="Статус"><option value="">Все статусы</option>${opts(['Новое','Повторить','Изучено'],status)}</select><select id="sourceFilter" aria-label="Вкладка"><option value="">Все вкладки</option>${opts(sheets.filter(s=>!s.excluded&&s.chineseRows).map(s=>s.name),sourceFilter)}</select><select id="quality" aria-label="Полнота записи"><option value="">Все записи</option><option value="complete" ${quality==='complete'?'selected':''}>С переводом и пиньинем</option><option value="missing" ${quality==='missing'?'selected':''}>Нужно дополнить</option><option value="auto" ${quality==='auto'?'selected':''}>Проверить автопиньинь</option></select>${view!=='tech'?`<label class="check"><input type="checkbox" id="onlyWork" ${onlyWork?'checked':''}> Только площадка</label>`:''}<button id="reset">Сбросить</button></div></details>`}
function exampleHTML(ex){return `<div class="example"><div class="zh">${esc(ex.zh)}</div><div class="py">${esc(ex.py)}</div><div>${esc(ex.ru)}</div>${ex.origin?`<small class="sub">${esc(ex.origin)}${ex.source?.url?` · <a href="${esc(ex.source.url)}" target="_blank" rel="noopener">${esc(ex.source.sheet)} · строка ${esc(ex.source.row)}</a>`:''}</small>`:''}${ex.pyOrigin==='Автоматически'?'<small class="sub">Пиньинь сформирован автоматически</small>':''}</div>`}
function starHTML(d){return `<button class="favorite-star ${d.favorite?'starred':''}" data-star="${esc(d.id)}" aria-label="${d.favorite?'Убрать из избранного':'Добавить в избранное'}" title="${d.favorite?'Убрать из избранного':'Добавить в избранное'}" aria-pressed="${!!d.favorite}">${d.favorite?'★':'☆'}</button>`}
function examplePriority(e){const o=e.origin||'';return /исходн|таблиц|вручную/i.test(o)||(!o&&e.source)?0:!o?1:2}
function examplesHTML(d){const examples=[...(d.examples||[])].sort((a,b)=>examplePriority(a)-examplePriority(b));if(!examples.length)return '';return exampleHTML(examples[0])+(examples.length>1?`<details class="more-examples"><summary>Ещё примеры (${examples.length-1})</summary>${examples.slice(1).map(exampleHTML).join('')}</details>`:'')}
function analysisPrompt(d){return `Разбери китайское слово или фразу: «${d.zh}». Ответь по-русски: дай пиньинь и перевод, объясни значение, слова и грамматику, расскажи, как употреблять. Приведи два естественных примера на китайском с пиньинем и переводом на русский.`}
function deepSeekHTML(d){return `<button type="button" class="google-word deepseek-word" data-deepseek-prompt="${esc(analysisPrompt(d).replace('два естественных примера','три естественных примера'))}" aria-label="Разобрать ${esc(d.zh)} в DeepSeek" title="Поделиться фразой для разбора"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 16V3m-4 4 4-4 4 4M5 12v7a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-7"/></svg></button>`}
function deepSeekFallback(prompt,copied){const dialog=document.createElement('dialog');const title=document.createElement('h2');title.textContent='Разбор в DeepSeek';const note=document.createElement('p');note.textContent=copied?'Запрос скопирован. Открой DeepSeek, вставь его в чат и отправь.':'Скопируй запрос ниже, затем вставь его в DeepSeek.';const text=document.createElement('textarea');text.value=prompt;text.rows=7;const copy=document.createElement('button');copy.textContent='Скопировать запрос';copy.onclick=async()=>{copy.textContent=await copyAnalysisPrompt(prompt)?'Скопировано ✓':'Выдели текст и скопируй вручную'};const open=document.createElement('a');open.href='https://chat.deepseek.com/';open.target='_blank';open.rel='noopener noreferrer';open.textContent='Открыть DeepSeek →';const close=document.createElement('button');close.textContent='Закрыть';close.onclick=()=>dialog.close();dialog.append(title,note,text,copy,open,close);dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal()}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-deepseek-prompt]');if(!button)return;const prompt=button.dataset.deepseekPrompt;if(/Android/i.test(navigator.userAgent)&&navigator.share){try{await navigator.share({title:'Разбор китайской фразы',text:prompt});return}catch(error){if(error.name==='AbortError')return}}const target=!/Android/i.test(navigator.userAgent)?window.open('about:blank','_blank'):null;if(target)target.opener=null;const copied=await copyAnalysisPrompt(prompt);if(target&&copied){target.location.href='https://chat.deepseek.com/';toast('Запрос скопирован — вставь его в DeepSeek и отправь.')}else{if(target)target.close();deepSeekFallback(prompt,copied)}});
async function copyAnalysisPrompt(text){try{await navigator.clipboard.writeText(text);return true}catch{}const field=document.createElement('textarea');field.value=text;field.style.cssText='position:fixed;top:0;left:0;opacity:0';(document.querySelector('dialog[open]')||document.body).append(field);field.focus();field.select();let copied=false;try{copied=document.execCommand('copy')}catch{}field.remove();return copied}

function cardHTML(d){return `<article class="item" data-word-id="${esc(d.id)}">${starHTML(d)}${deepSeekHTML(d)}<div class="topic-strip">${d.tags.slice(0,5).map(t=>`<button class="pill ${(selectedTopics.has(t)||topic===t)?'active':''}" aria-pressed="${(selectedTopics.has(t)||topic===t)}" data-category="${esc(t)}">${esc(t)}</button>`).join('')}${d.tags.length>5?`<span class="pill">+${d.tags.length-5}</span>`:''}</div><div class="zh">${esc(d.zh)}</div><div class="py">${esc(d.py)||'Пиньинь не заполнен'}</div><div class="ru">${d.ru?esc(d.ru):'<span class="no-translation">Перевод не найден в источнике — нужно дополнить</span>'}</div>${view==='slang'?`${d.level&&d.level!=='Уровень не указан'?`<span class="tag">${esc(d.level)}</span>`:''}${d.quality&&d.quality!=='Словарь с телефона · редактура'?` <span class="tag ${d.pyOrigin==='Автоматически'||!d.complete?'warn':''}">${esc(d.quality)}</span>`:''}`:`<div style="margin-top:10px"><span class="tag">${esc(d.level)}</span> <span class="tag ${d.pyOrigin==='Автоматически'||!d.complete?'warn':''}">${esc(d.quality||'Добавлено вручную')}</span></div>`}${view==='slang'&&d.slangNote&&d.slangNote!=='Неформальная речь: уместность зависит от отношений и ситуации.'?`<p class="notice">${esc(d.slangNote)}</p>`:''}${view==='idioms'?idiomIntro(d):''}${examplesHTML(d)}${d.meanings?.length>1?`<details><summary>Другие значения из таблицы (${d.meanings.length-1})</summary>${d.meanings.filter(m=>m!==d.ru).slice(0,10).map(m=>`<p>${esc(m)}</p>`).join('')}</details>`:''}<details><summary>Источники и темы (${d.sources.length||1})</summary><p>${d.tags.map(esc).join(' · ')}</p>${d.sources.slice(0,20).map(s=>`${s.url?`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.sheet)} · строка ${s.row}</a>`:`<span class="source-link">${esc(s.sheet)} · строка ${s.row}</span>`}`).join('')||esc(d.source)}${d.sources.length>20?`<p>Всего источников: ${d.sources.length}. Все входят в экспорт.</p>`:''}${d.originalChinese?`<p>Оригинал: ${esc(d.originalChinese)}<br>${esc(d.correctionNote||'Исправлена запись.')}</p>`:''}${d.originalPinyin&&d.originalPinyin!==d.py?`<p>Пиньинь в источнике: ${esc(d.originalPinyin)}</p>`:''}</details><footer>${view==='repeat'?`<button class="primary" data-memorized="${esc(d.id)}">Запомнил</button>`:''}<small class="sub">${esc(d.state)} · ${d.sources.length>1?d.sources.length+' источников':esc(d.source)}</small><button data-edit="${esc(d.id)}">Изменить</button></footer></article>`}
function pagination(total,size=24){const pages=Math.max(1,Math.ceil(total/size));return `<div class="paging"><button id="prev" ${page===0?'disabled':''}>← Назад</button><span>${page+1} / ${pages}</span><button id="more" ${page+1>=pages?'disabled':''}>Дальше →</button></div>`}
const shuffledOrders=new Map();
function shuffledViewItems(items,key,idOf){const order=shuffledOrders.get(key);if(!order)return items;return items.map((item,index)=>({item,index,order:order.get(idOf(item))??Number.MAX_SAFE_INTEGER})).sort((a,b)=>a.order-b.order||a.index-b.index).map(x=>x.item)}
let listPending=[],listObserver=null,listRenderer=cardHTML;
let idiomDifficulty='';
function idiomBand(d){if(['HSK 1','HSK 2','HSK 3','HSK 4'].includes(d.level))return 'Лёгкие';if(d.level==='HSK 6'||d.zh.length>12)return 'Сложные';return 'Средние'}
function idiomIntro(d){const ex=d.examples?.[0];return `<div class="notice"><p>Смысл выражения: ${esc(d.ru)}. ${d.zh.length===4?'Это компактная четырёхиероглифная форма; её значение нужно запоминать целиком.':'В этой подборке есть также пословицы, устойчивые обороты и фразы с ними.'}</p><p>${ex?`Употребление в контексте: ${esc(ex.zh)} (${esc(ex.py)}) — ${esc(ex.ru)}.`:'Используй выражение, когда ситуация соответствует его переносному смыслу; перед употреблением проверь контекст в Google.'} Исторический источник в исходной базе не указан.</p></div>`}
function listHTML(){if(view==='idioms'&&!idiomDifficulty)return `<h1>Идиомы</h1><p class="sub">Выбери сложность. Уровни ориентировочные: по HSK и длине выражения.</p><div class="grid">${['Лёгкие','Средние','Сложные'].map(b=>`<button class="panel" data-idiom-band="${b}"><h2>${b}</h2>${filtered().filter(d=>idiomBand(d)===b).length} выражений →</button>`).join('')}</div>`;let f=filtered();if(view==='idioms')f=f.filter(d=>idiomBand(d)===idiomDifficulty);if(['repeat','remembered','favorites'].includes(view))f.sort((a,b)=>(Number(view==='favorites'?b.favoriteAt:b.memoryAt)||0)-(Number(view==='favorites'?a.favoriteAt:a.memoryAt)||0));f=shuffledViewItems(f,view,d=>d.id);listPending=f;listRenderer=cardHTML;return `<h1>${view==='equipment'?'Оборудование':view==='slang'?'Сленг и разговорные выражения':view==='remembered'?'Помню':view==='idioms'?'Идиомы и устойчивые выражения':view==='repeat'?'Нужно повторить':view==='favorites'?'Избранные слова':view==='tech'?'На промышленной площадке':'Вся база знаний'}</h1><p class="sub">${view==='repeat'?'Здесь слова, отмеченные «Не помню», и ошибки из тестов. «Помню» убирает слово из этого списка.':view==='favorites'?'Твоя личная подборка. Звёздочка добавляет или убирает слово.':view==='equipment'?'Оборудование, трубопроводы, арматура, инструменты и связанные рабочие выражения.':view==='tech'?'Рабочие термины из всех вкладок. Одна запись может относиться к нескольким темам.':'Слова, фразы, грамматика и примеры из всей таблицы. Дубли объединены, ссылки на источники сохранены.'}</p>${['tech','base'].includes(view)?`<div class="topic-strip">${allTopics(view==='tech').map(t=>`<button class="${(selectedTopics.has(t)||topic===t)?'active':''}" aria-pressed="${(selectedTopics.has(t)||topic===t)}" data-category="${esc(t)}">${t}</button>`).join('')}</div>`:''}${topic==='SIMOPS'?'<p class="notice">SIMOPS — междисциплинарная подборка: монтаж, подъём, сварка, электрика, допуски, изоляция, координация и графики. Метка означает полезность для совмещённых работ; сама по себе она не означает, что работы выполняются одновременно.</p>':''}${view==='idioms'?`<button data-idiom-band="">← Все уровни</button><h2>${idiomDifficulty}</h2>`:''}${filters()}<div class="summaryline"><p class="sub">Найдено ${num(f.length)}</p><div><button id="shuffleCards" aria-label="Перемешать карточки">⤨ Перемешать</button> <button id="practiceFiltered">Карточки по выборке</button> <button id="testFiltered">Тест по выборке</button></div></div><div class="grid" id="allListCards">${f.slice(0,100).map(cardHTML).join('')||'<div class="empty">Нет записей по этим условиям. Сбрось фильтры или добавь материал.</div>'}</div>${f.length>100?'<div id="listSentinel" aria-label="Загрузка остальных карточек"></div>':''}`}
function homeHTML(){const a=corpus.audit||{},counts={};data.filter(d=>d.work).forEach(d=>d.tags.forEach(t=>counts[t]=(counts[t]||0)+1));return `<h1>Китайский для твоей площадки.</h1><p class="sub">Вся языковая база собрана вместе. Рабочие материалы — на первом месте.</p><section class="hero"><div><span class="tag">МОНТАЖ · КООРДИНАЦИЯ · SIMOPS</span><h2>От термина — к рабочему разговору</h2><p>Ищи по всей таблице, повторяй фразы и собирай темы под текущую задачу. Исходные записи доступны рядом с обработанной базой.</p><button data-go="tech">Открыть рабочую базу →</button></div><div class="art">工</div></section><div class="stats"><div class="stat">Всего уникальных записей<b>${num(data.length)}</b><small>слова, фразы и конструкции</small></div><div class="stat">Для рабочей площадки<b>${num(data.filter(d=>d.work).length)}</b><small>включая несколько тематик</small></div><div class="stat">Языковых вкладок<b>${a.languageSheets||0}</b><small>из ${a.sheets||50} вкладок исходника</small></div></div><h2 style="margin-top:30px">Выбери рабочую тему</h2><div class="category-grid">${WORK_TOPICS.filter(t=>counts[t]).map(t=>`<button class="category" data-category="${esc(t)}"><span>${esc(t)}</span><b>${num(counts[t])}</b></button>`).join('')}</div><div class="notice">Обновлено 8 ноября 2026 из Google-таблицы. Переводы дополнены, пиньинь приведён к словарной транскрипции. ${num(corpus.audit?.archivedFragments||0)} неоднозначных обрывков сохранены в исходниках. Исправления и оригиналы доступны в каждой записи.</div><h2>Повторение и тесты</h2><div class="grid"><div class="panel"><h2>Вспомнить рабочие термины</h2><p class="sub">Иероглифы → ответ → оценка. Записи без перевода в повторение не попадают.</p><button data-go="cards">Начать повторение →</button></div><div class="panel"><h2>Проверить себя</h2><p class="sub">Новые вопросы по базе: 20 терминов в сессии. Есть отдельный режим HSK 4–5.</p><button data-go="quiz">Начать тест →</button></div></div>`}
