const hanCount=s=>(s.match(/[\u3400-\u9fff]/g)||[]).length;
let reviewPhraseIndex=null;
function reviewPrompt(d){
 if(hanCount(d.zh)>=4)return d;
 const explicit=REVIEW_PHRASES[d.zh];if(explicit)return {zh:explicit[0],py:explicit[1],ru:explicit[2]};
 if(!reviewPhraseIndex){reviewPhraseIndex=new Map();for(const word of data){const n=hanCount(word.zh);if(n<4||n>10||!word.complete||/[，。！？；：]/.test(word.zh))continue;for(let len=1;len<=3;len++)for(let i=0;i<=word.zh.length-len;i++){const key=word.zh.slice(i,i+len),old=reviewPhraseIndex.get(key);if(!old||word.zh.length<old.zh.length)reviewPhraseIndex.set(key,word)}}}
 return reviewPhraseIndex.get(d.zh)||null;
}
function reviewEligible(d){return d.complete&&!!reviewPrompt(d)}
let reviewAnswered=new Set(),reviewSessionQueue=null;
function ensureReview(){if(reviewQueue.length)return;reviewAnswered=new Set();reviewQueue=shuffled(filtered().filter(reviewEligible)).map(d=>d.id);reviewAt=0;reviewDone=0}
let reviewRepeatSlots=new Set(),reviewRepeatQueue=null;
function reviewHTML(){ensureReview();if(reviewRepeatQueue!==reviewQueue){reviewRepeatQueue=reviewQueue;reviewRepeatSlots=new Set()}if(reviewAt>0&&reviewAt%4===0&&!reviewRepeatSlots.has(reviewAt)){const pool=data.filter(d=>d.state==='Повторить'&&reviewEligible(d)&&d.id!==reviewQueue[reviewAt-1]);if(pool.length)reviewQueue.splice(reviewAt,0,shuffled(pool)[0].id);reviewRepeatSlots.add(reviewAt)}if(reviewSessionQueue!==reviewQueue){reviewSessionQueue=reviewQueue;reviewAnswered=new Set();reviewDone=0}revealed=reviewAnswered.has(reviewAt);const d=data.find(d=>d.id===reviewQueue[reviewAt]),prompt=d?reviewPrompt(d):null;return `<h1>Карточки</h1>${d?`<section class="panel review" data-word-id="${esc(d.id)}"><button class="review-arrow review-arrow-back" id="reviewBack" aria-label="Предыдущая карточка" ${reviewAt===0?'disabled':''}>‹</button><button class="review-arrow review-arrow-forward" id="reviewForward" aria-label="Следующая карточка">›</button>${starHTML(d)}${deepSeekHTML(d)}<div class="review-count">Карточка ${Math.min(reviewAt+1,reviewQueue.length)} из ${reviewQueue.length} · Отмечено: ${reviewAnswered.size}</div><span class="tag">${esc(d.topic)}</span><div class="zh">${esc(prompt?.zh||d.zh)}</div>${revealed?`<div class="py">${esc(prompt?.py||d.py)}</div><h2>${esc(prompt?.ru||d.ru)}</h2>${prompt?.zh!==d.zh?`<p class="sub">Исходное слово: ${esc(d.zh)} · ${esc(d.py)} · ${esc(d.ru)}</p>`:''}${examplesHTML(d)}<p class="sub">${d.state==='Изучено'?'Отмечено: помню':'Добавлено в список «Повторить»'}</p>${d.state==='Изучено'?'<button id="undoRemember">А нет, не помню</button>':''}`:`<div class="bar" style="justify-content:center"><button data-memory="again">Не помню</button><button data-memory="know" class="primary">Помню</button></div>`}</section>`:`<section class="panel empty"><button id="reviewBack" aria-label="Предыдущая карточка">← Назад</button><h2>Все слова этой подборки пройдены</h2><button id="reviewAll">Перемешать и повторить</button></section>`}<details><summary>Выбрать слова и категории</summary>${filters()}</details>`}

function shuffled(a){return a.map(x=>({x,n:Math.random()})).sort((a,b)=>a.n-b.n).map(x=>x.x)}
function startQuiz(pool){quizStarted=true;const valid=pool.filter(d=>d.complete&&d.zh.length<=55&&d.ru.length<=220);quiz=[];wrong=[];quizAt=score=0;answered=false;const selected=shuffled(valid).slice(0,10);for(const d of selected){const seen=new Set([norm(d.zh),norm(d.ru)]);let options=[d];let distractors=shuffled(valid.filter(x=>x.id!==d.id)).sort((a,b)=>(b.tags.includes(d.topic)?1:0)-(a.tags.includes(d.topic)?1:0));for(const x of distractors){if(seen.has(norm(x.zh))||seen.has(norm(x.ru)))continue;options.push(x);seen.add(norm(x.zh));seen.add(norm(x.ru));if(options.length===4)break}if(options.length===4)quiz.push({d,options:shuffled(options)})}}
const LIFE_TOPICS=['Общая лексика','Еда и кофе','Семья и отношения','Путешествия и транспорт','Разговорная речь','Тело и здоровье','Эмоции и общение','Погода и природа','Бильярд','Го','Обучение и развитие','Числа и измерения'];
const QUIZ_GROUPS={'Все':'Вся база','Площадка':'Площадка и работа','Жизнь':'Повседневная жизнь','Идиомы':'Идиомы · 成语','HSK 4–5':'Уровни HSK 4–5'};
function isIdiom(d){return d.tags.includes('Идиомы')||d.sources.some(s=>/成语|идиомы/i.test(s.sheet))}
function quizGroupPool(){if(quizMode!=='Выборка')return data;return quizMode==='Выборка'?data.filter(d=>quizSelection.includes(d.id)):data.filter(d=>quizMode==='Все'||quizMode==='Площадка'&&d.work||quizMode==='Жизнь'&&!d.work&&!isIdiom(d)&&d.tags.some(t=>LIFE_TOPICS.includes(t))||quizMode==='Идиомы'&&isIdiom(d)||quizMode==='HSK 4–5'&&['HSK 4','HSK 5'].includes(d.level))}
function quizPool(){return quizGroupPool().filter(d=>!quizTopic||d.tags.includes(quizTopic))}
function quizValid(pool){return pool.filter(d=>d.complete&&d.zh.length<=55&&d.ru.length<=220)}
function quizHTML(){const q=quiz[quizAt];answered=Number.isInteger(q?.picked);quizPicked=answered?q.picked:-1;const available=quizValid(quizPool()).length,topics=[...new Set(quizGroupPool().flatMap(d=>d.tags))].sort((a,b)=>a.localeCompare(b,'ru'));return `<h1>Тесты по темам</h1><section class="panel quiz-settings"><div class="grid"><label>Тема теста<select id="quizTopic" aria-label="Тема теста"><option value="">Все темы</option>${opts(topics,quizTopic)}</select></label></div><p class="sub">Подходит для теста: ${num(available)} записей · до 10 вопросов</p><button id="newQuiz" class="primary" ${available<4?'disabled':''}>${quizStarted?'Начать новый тест':'Начать тест'}</button>${available<4?'<p class="notice">В этой теме нужно минимум 4 разных выражения с разными переводами. Выбери другую тему или раздел.</p>':''}</section>${!quizStarted?'':!quiz.length?'<section class="panel"><p>Недостаточно разных ответов для теста. Выбери более широкую тему.</p></section>':`<section class="panel" style="margin-top:18px">${q?`<span class="sub">${esc(QUIZ_GROUPS[quizMode]||'Выбранные слова')} · ${esc(quizTopic||'Все темы')}<br>Вопрос ${quizAt+1} из ${quiz.length} · Верно: ${score}</span><progress max="${quiz.length}" value="${quizAt}"></progress><h2 data-question-start tabindex="-1">${esc(q.d.ru)}</h2><span class="tag">${esc(q.d.topic)}</span><div class="options">${q.options.map((d,i)=>`<button class="${answered?(d.id===q.d.id?'good':i===quizPicked?'wrong':''):''}" data-answer="${i}" ${answered?'disabled':''}>${'ABCD'[i]}　${esc(d.zh)}</button>`).join('')}</div><div id="feedback" aria-live="polite">${answered?quizFeedbackHTML(q):''}</div><div class="bar"><button id="quizBack" ${quizAt===0?'disabled':''}>← Предыдущий вопрос</button><button id="quizForward" ${!answered?'disabled':''}>${quizAt+1===quiz.length?'Завершить':'Следующий вопрос →'}</button></div>`:`<h2 data-question-start tabindex="-1">Тест завершён</h2><button id="otherQuiz" class="primary">Тест на другую тему →</button>`}</section>`}<p class="notice">Вопросы формируются из твоей базы. Это тренажёр лексики, а не полный экзамен HSK.</p>`}
let sourcesLoading=false,sourcesError='';async function loadSources(){if(corpus.raw?.length||sourcesLoading)return;sourcesLoading=true;sourcesError='';try{const r=await fetch(corpus.rawUrl||'/raw.json');if(!r.ok)throw Error();corpus.raw=await r.json();rebuild()}catch{sourcesError='Не удалось загрузить исходные строки. Нажми «Повторить загрузку».'}finally{sourcesLoading=false;if(view==='import')render()}}
function sourceRowHTML(r){return `<article class="item" style="margin:12px 0"><div class="summaryline"><span class="tag">${esc(r.source)} · строка ${r.row}</span><span class="tag">${r.parsed?'Есть в словаре':r.note?'Заметка / заголовок':'Нужен разбор'}</span></div><p class="raw">${esc(r.text)}</p><details><summary>Показать всю строку по столбцам</summary><div class="sourcetext">${(r.cells||[{col:1,text:r.text}]).map(c=>`<div class="source-cell"><b>Столбец ${c.col}</b><div>${esc(c.text)}</div></div>`).join('')}</div></details><div class="bar"><button data-process="${esc(r.id)}">Создать запись из строки</button><button data-related="${esc(r.id)}">Записи из этой строки</button><button data-mark="${esc(r.id)}">${completed.includes(r.id)?'Снять отметку':'Отметить обработанной'}</button></div></article>`}
function sourceHTML(){if(!corpus.raw?.length){return `<h1>Источники и перенос</h1><p class="notice">${sourcesError||'Загружаю исходные строки. Словарь уже доступен в остальных разделах.'}</p>${sourcesError?'<button id="reloadSources">Повторить загрузку</button>':''}`} let q=query.toLowerCase();const f=raw.filter(r=>(!sourceFilter||r.source===sourceFilter)&&(!q||r.text.toLowerCase().includes(q))&&(!quality||(quality==='unparsed'?!r.parsed:quality==='pending'?!completed.includes(r.id):true)));listPending=f;listRenderer=sourceRowHTML;let a=corpus.audit||{};return `<h1>Вся таблица внутри приложения</h1><p class="sub">Обработанная база и полный текст исходных материалов — два способа смотреть на одни знания.</p><div class="notice">Источник: Google-таблица «Китайский». Снимок базы от 8 ноября 2026. Вкладки «с телефона», «по темам» и «СЛОВА» сверены 10 ноября 2026. Автоматического обновления по расписанию нет. Личные контакты, расходы, валютные расчёты и журнал занятий исключены из учебной базы. Остальные материалы доступны ниже с исходными столбцами.</div><div class="bar"><button id="export" class="primary">Экспорт всей базы JSON</button><button id="exportCSV">Словарь в CSV</button><button id="upload">Импорт JSON / CSV / TSV</button><input id="file" type="file" accept=".json,.csv,.tsv" hidden></div><details class="panel"><summary>Что перенесено: отчёт по всем ${a.sheets||50} вкладкам</summary><p>Исходных непустых строк: ${num(a.sourceRows||0)}. Разобрано строк с китайским: ${num(a.parsedRows||0)}. Уникальных записей: ${num(a.records||0)}. Обрывки без достаточного контекста сохранены в исходных строках. Все активные карточки имеют перевод и пиньинь.</p><div class="scrolltable"><table><thead><tr><th>Вкладка</th><th>Непустые строки</th><th>С китайским</th><th>Новые записи*</th><th>Статус</th></tr></thead><tbody>${sheets.map(s=>`<tr><td>${esc(s.name)}</td><td>${num(s.rows||0)}</td><td>${num(s.chineseRows||0)}</td><td>${num(s.records||0)}</td><td>${s.excluded?esc(s.excluded):s.empty?'Пустая':s.chineseRows?'Перенесена':'Заметки без китайского'}</td></tr>`).join('')}</tbody></table></div><p class="sub">* Новые уникальные записи при последовательном объединении вкладок. Повторы хранятся как дополнительные источники существующей записи.</p></details><details class="panel" style="margin-top:12px"><summary>Добавить строки из Google Sheets</summary><p>Вставь строки с заголовками zh, py, ru, topic, tags, level, ex, ep, er, source. Без заголовков текст попадёт в источники для ручного разбора.</p><textarea id="paste" class="wide-input" placeholder="Строки, скопированные из таблицы…"></textarea><button id="parse">Добавить в очередь</button></details><div class="bar"><input id="search" aria-label="Поиск в источниках" placeholder="Поиск по полному тексту исходника…" value="${esc(query)}"><select id="sourceFilter" aria-label="Вкладка"><option value="">Все вкладки</option>${opts([...new Set(raw.map(r=>r.source))],sourceFilter)}</select><select id="quality"><option value="">Все строки</option><option value="unparsed" ${quality==='unparsed'?'selected':''}>Не извлечены в словарь</option><option value="pending" ${quality==='pending'?'selected':''}>Не отмечены обработанными</option></select></div><p class="sub">Найдено строк: ${num(f.length)} · отмечено обработанными: ${num(completed.length)}</p><div id="allListCards">${f.slice(0,100).map(sourceRowHTML).join('')||'<div class="empty">Строки не найдены.</div>'}</div>${f.length>100?'<div id="listSentinel"></div>':''}`}
