function bind(){document.querySelectorAll('[data-idiom-band]').forEach(b=>b.onclick=()=>{idiomDifficulty=b.dataset.idiomBand;render()});if($('#quizBack'))$('#quizBack').onclick=()=>{quizAt--;render();scrollToQuestion()};if($('#quizForward'))$('#quizForward').onclick=advanceQuiz;if($('#otherQuiz'))$('#otherQuiz').onclick=()=>{const topics=[...new Set(data.flatMap(d=>d.tags))].filter(t=>t!==quizTopic&&quizValid(data.filter(d=>d.tags.includes(t))).length>=4);quizMode='Все';quizTopic=shuffled(topics)[0]||'';startQuiz(quizPool());render();scrollToQuestion()};document.querySelectorAll('[data-daily-word]').forEach(button=>button.onclick=()=>{const day=dailyToday(),words=dailyWords(day);dailyTraining[day]??={};dailyTraining[day].wordIds??=words.map(d=>d.id);dailyTraining[day].viewedWords??=[];if(!dailyTraining[day].viewedWords.includes(button.dataset.dailyWord)){dailyTraining[day].viewedWords.push(button.dataset.dailyWord);recordPractice('cards')}persist();render()});if($('#next'))$('#next').onclick=advanceQuiz;document.querySelectorAll('[data-training-step]').forEach(input=>input.onchange=()=>{dailySet(dailyToday(),input.dataset.trainingStep,input.checked);render()});document.querySelectorAll('[data-daily-answer]').forEach(button=>button.onclick=()=>{const day=dailyToday(),qid=button.dataset.dailyAnswer,q=dailyQuestions(day).find(x=>x.d.id===qid);if(!q||dailyAnswered(day,qid))return;recordPractice('tests');dailySet(day,'answer:'+qid+':'+(button.dataset.dailyChoice===qid?'1':'0'),true);render()});if($('#shuffleCards'))$('#shuffleCards').onclick=()=>{const items=shuffled(filtered());shuffledOrders.set(view,new Map(items.map((d,i)=>[d.id,i])));page=0;render()};if($('#shuffleLessons'))$('#shuffleLessons').onclick=()=>{const items=shuffled((corpus.lessons||[]).filter(x=>lessonCategory==='Все'||x.category===lessonCategory));shuffledOrders.set('lessons',new Map(items.map((x,i)=>[x.category+'\u0000'+x.title,i])));render()};if($('#reviewBack'))$('#reviewBack').onclick=()=>{if(reviewAt>0){reviewAt--;render()}};if($('#reviewForward'))$('#reviewForward').onclick=()=>{if(reviewAt<reviewQueue.length){reviewAt++;render()}};if($('#lessonVocabulary'))$('#lessonVocabulary').onclick=()=>{nav('base');sourceFilter='Уроки 燕子';render()};document.querySelectorAll('[data-memorized]').forEach(b=>b.onclick=()=>{const d=data.find(x=>x.id===b.dataset.memorized);if(!d)return;update({...d,state:'Изучено',viewedAt:d.viewedAt||Date.now(),memoryAt:Date.now(),due:Date.now()+3*86400000});render();toast('Отмечено «Помню»')});if($('#undoRemember'))$('#undoRemember').onclick=()=>{const d=data.find(d=>d.id===reviewQueue[reviewAt]);if(!d)return;update({...d,state:'Повторить',memoryAt:Date.now(),due:Date.now()+60000});render()};for(const id of ['quizGroup','quizTopic'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='quizGroup'){quizMode=e.target.value;quizTopic=''}else quizTopic=e.target.value;quiz=[];quizStarted=false;render()};document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.star));if($('#reloadSources'))$('#reloadSources').onclick=loadSources;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{const category=b.dataset.category;if(selectedTopics.has(category))selectedTopics.delete(category);else selectedTopics.add(category);topic='';if(!['base','tech','repeat','favorites'].includes(view))view='tech';page=0;reviewQueue=[];render();window.scrollTo(0,0)});if($('#equipmentFilter'))$('#equipmentFilter').onclick=()=>{topic=topic==='Оборудование'?'':'Оборудование';selectedTopics.clear();onlyWork=false;filterChanged()};if($('#add'))$('#add').onclick=()=>edit();for(const k of ['topic','level','status','sourceFilter','quality'])if($('#'+k))$('#'+k).onchange=e=>{const v=e.target.value;if(k==='topic'){topic=v;selectedTopics.clear();}if(k==='level')level=v;if(k==='status')status=v;if(k==='sourceFilter')sourceFilter=v;if(k==='quality')quality=v;filterChanged()};if($('#onlyWork'))$('#onlyWork').onchange=e=>{onlyWork=e.target.checked;filterChanged()};if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;filterChanged();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#reset'))$('#reset').onclick=()=>{resetFilters();render()};if($('#prev'))$('#prev').onclick=()=>{page--;render();window.scrollTo(0,0)};if($('#more'))$('#more').onclick=()=>{page++;render();window.scrollTo(0,0)};if($('#practiceFiltered'))$('#practiceFiltered').onclick=()=>{const ids=shuffled(filtered().filter(reviewEligible)).map(d=>d.id);if(!ids.length){toast('В этой подборке пока нет слов.');return}if(view==='tech')onlyWork=true;view='cards';reviewQueue=ids;reviewAt=reviewDone=0;revealed=false;render()};if($('#testFiltered'))$('#testFiltered').onclick=()=>{const pool=filtered();if(pool.filter(d=>d.complete).length<4){toast('Нужно не менее 4 полных записей в выборке.');return}quizMode='Выборка';quizTopic='';quizSelection=pool.map(d=>d.id);startQuiz(pool);view='quiz';render();scrollToQuestion()};document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{if(revealed)return;const d=data.find(d=>d.id===reviewQueue[reviewAt]);update({...d,viewedAt:d.viewedAt||Date.now(),memoryAt:Date.now(),state:b.dataset.memory==='know'?'Изучено':'Повторить',due:Date.now()+(b.dataset.memory==='know'?3*86400000:60000)});recordPractice('cards');reviewAnswered.add(reviewAt);revealed=true;reviewDone=reviewAnswered.size;render()});if($('#nextCard'))$('#nextCard').onclick=()=>{reviewAt++;revealed=false;render()};if($('#reveal'))$('#reveal').onclick=()=>{revealed=true;render()};document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{const d=data.find(d=>d.id===reviewQueue[reviewAt]);if(!d)return;const action=b.dataset.rate;update({...d,state:action==='know'?'Изучено':'Повторить',memoryAt:Date.now(),due:Date.now()+(action==='know'?3*86400000:action==='tomorrow'?86400000:60000)});if(!reviewAnswered.has(reviewAt)){recordPractice('cards');reviewAnswered.add(reviewAt)}if(action==='again')reviewQueue.push(d.id);reviewAt++;reviewDone=reviewAnswered.size;revealed=false;render()});if($('#reviewAll'))$('#reviewAll').onclick=()=>{reviewQueue=shuffled(filtered().filter(reviewEligible)).map(d=>d.id);reviewAt=reviewDone=0;revealed=false;render()};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{quizMode=b.dataset.mode;quizTopic='';quizStarted=false;quiz=[];render()});for(const id of ['newQuiz','newQuizBottom'])if($('#'+id))$('#'+id).onclick=()=>{startQuiz(quizPool());render();scrollToQuestion()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));document.querySelectorAll('[data-process]').forEach(b=>b.onclick=()=>edit(null,raw.find(r=>r.id===b.dataset.process)));document.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const id=b.dataset.mark;completed=completed.includes(id)?completed.filter(x=>x!==id):[...completed,id];persist();render()});document.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>{const r=raw.find(x=>x.id===b.dataset.related),found=data.filter(d=>d.sources.some(s=>s.sheet===r.source&&s.row===r.row));if(!found.length){toast('Строка ещё не преобразована в словарь. Создай запись вручную.');return}showRelated(r,found)});if($('#export'))$('#export').onclick=exportJSON;if($('#exportCSV'))$('#exportCSV').onclick=exportCSV;if($('#upload')){$('#upload').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(f)await importFile(f)};$('#parse').onclick=()=>ingest($('#paste').value,'Вставка из таблицы')}}
function setupListLoading(){if(listObserver){listObserver.disconnect();listObserver=null}const sentinel=document.querySelector('#listSentinel'),container=document.querySelector('#allListCards');if(!sentinel||!container)return;let at=100;function append(){if(!sentinel.isConnected)return;const batch=listPending.slice(at,at+100);at+=batch.length;container.insertAdjacentHTML('beforeend',batch.map(listRenderer).join(''));bind();observeWords();if(at>=listPending.length){listObserver?.disconnect();sentinel.remove()}}if(!('IntersectionObserver'in window)){while(at<listPending.length)append();return}listObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))append()},{rootMargin:'1200px'});listObserver.observe(sentinel)}
function renderNextFloating(){document.querySelector('#floatingAdvance')?.remove();let next=null;if(view==='quiz')next=document.querySelector('#next');else if(view==='business')next=document.querySelector('#businessQuestionNext');else if(view==='cards'&&revealed)next=document.querySelector('#reviewForward');if(!next||next.disabled)return;const button=document.createElement('button');button.id='floatingAdvance';button.className='floating-advance';button.type='button';button.setAttribute('aria-label',view==='cards'?'Следующая карточка':'Следующий вопрос');button.title=button.getAttribute('aria-label');button.textContent='→';button.onclick=()=>{next.click();if(view==='cards')document.querySelector('.review')?.scrollIntoView({block:'start',behavior:'smooth'})};document.body.append(button)}
function scrollToQuestion(){requestAnimationFrame(()=>{const target=document.querySelector('[data-question-start]');if(!target)return;target.focus({preventScroll:true});window.scrollTo({top:Math.max(0,target.getBoundingClientRect().top+window.scrollY-16),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})})}
function quizFeedbackHTML(q){const ok=q.options[quizPicked]?.id===q.d.id;return `<div class="${ok?'ok':'bad'}">${ok?'Верно':'Правильный ответ'}<div class="zh">${esc(q.d.zh)}</div><div class="py">${esc(q.d.py)}</div><div>${esc(q.d.ru)}</div>${examplesHTML(q.d)}</div>`}
function advanceQuiz(){if(!answered)return;quizAt++;answered=false;quizPicked=-1;render();scrollToQuestion()}
function answer(i){if(answered)return;const q=quiz[quizAt];if(!q?.options[i])return;recordPractice('tests');q.picked=i;answered=true;quizPicked=i;const ok=q.options[i].id===q.d.id;if(ok)score++;else{wrong.push(q.d);update({...q.d,state:'Повторить',memoryAt:Date.now(),due:Date.now()})}history.push({time:Date.now(),id:q.d.id,ok,mode:quizMode});persist();render()}

function showRelated(r,found){let dlg=document.createElement('dialog');dlg.innerHTML=`<h2>${esc(r.source)} · строка ${r.row}</h2><p>Найдено записей: ${found.length}</p>${found.map(d=>`<div class="source-cell"><div class="zh">${esc(d.zh)}</div><div class="py">${esc(d.py)}</div>${esc(d.ru)||'Нужен перевод'}</div>`).join('')}<p><button>Закрыть</button></p>`;document.body.append(dlg);dlg.querySelector('button').onclick=()=>dlg.close();dlg.onclose=()=>dlg.remove();dlg.showModal()}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportJSON(){if(!corpus.raw?.length)await loadSources();download('my-chinese-full-backup.json',JSON.stringify({version:2,exported:new Date().toISOString(),data:data.map(({_search,...d})=>d),raw,completed,history,sheets,writing:Object.fromEntries(writingRecords),deleted,sourceUrl:corpus.sourceUrl}), 'application/json');toast('Экспорт подготовлен. Сохрани файл как резервную копию.')}
function exportCSV(){const keys=['zh','py','ru','topic','tags','level','work','source','ex','ep','er'];const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('my-chinese-dictionary.csv','\ufeff'+[keys,...data.map(d=>keys.map(k=>k==='tags'?d.tags.join(', '):d[k]))].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split('\n')[0],sep=first.includes('\t')?'\t':first.includes(';')?';':',';let rows=[],r=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){r.push(v);v=''}else if(c==='\n'&&!quoted){r.push(v.replace(/\r$/,''));rows.push(r);r=[];v=''}else v+=c}if(quoted)throw Error('Незакрытые кавычки CSV');if(v||r.length){r.push(v);rows.push(r)}return rows}
function ingest(text,source){try{const rows=parseCSV(text),headers=(rows[0]||[]).map(x=>x.trim().toLowerCase()),known=headers.includes('zh');let n=0,dups=0;for(const [i,r]of rows.slice(known?1:0).entries()){if(!r.some(x=>x.trim()))continue;const candidate=known?Object.fromEntries(headers.map((h,j)=>[h,r[j]?.trim()||''])):{};if(candidate.zh&&candidate.ru&&candidate.py){if(data.some(d=>norm(d.zh)===norm(candidate.zh))){dups++;continue}candidate.id='user-'+uuid();candidate.tags=(candidate.tags||candidate.topic||'Общая лексика').split(',').map(s=>s.trim()).filter(Boolean);candidate.topic=candidate.topic||candidate.tags[0];candidate.work=candidate.work==='true'||candidate.tags.some(t=>WORK_TOPICS.includes(t));candidate.source=candidate.source||source;candidate.quality='Импортировано вручную';update(candidate)}else extraRaw.push({id:'import-'+uuid(),source,row:i+(known?2:1),text:r.join(' | '),candidate,cells:r.map((text,j)=>({col:j+1,text}))});n++}rebuild();persist();render();toast(`Добавлено: ${n}; повторов пропущено: ${dups}`)}catch(e){toast('Импорт не выполнен: '+e.message)}}
