function dailyOrder(items,day,key='id'){return [...items].sort((a,b)=>dailyHash(day+':'+a[key])-dailyHash(day+':'+b[key]))}
function dailyWords(day){const wrongIds=new Set(history.filter(x=>!x.ok).slice(-160).map(x=>x.id));const valid=data.filter(d=>d.complete&&d.py&&d.ru);const savedIds=dailyTraining[day]?.wordIds;if(savedIds?.length){const byId=new Map(data.map(d=>[d.id,d]));return savedIds.map(id=>byId.get(id)).filter(Boolean)}const rank=d=>d.state==='Повторить'?0:wrongIds.has(d.id)?1:d.state==='Изучено'?3:2;return [...valid].sort((a,b)=>rank(a)-rank(b)||dailyHash(day+':'+a.id)-dailyHash(day+':'+b.id)).slice(0,day>='2026-11-13'?6:5)}
