function dailyHistoryHTML(day){return Array.from({length:14},(_,i)=>{const date=new Date(`${day}T12:00:00`);date.setDate(date.getDate()-13+i);const key=date.toLocaleDateString('sv-SE'),n=dailyStatus(key),total=dailyTotal(key),label=date.toLocaleDateString('ru-RU',{day:'numeric',month:'short'});return `<div class="daily-day ${n===total?'done':n?'partial':''}" title="${label}: ${n===total?'тренировка пройдена':n?`выполнено этапов: ${n} из ${total}`:'тренировки пока нет'}"><span>${label}</span><b aria-label="${n===total?'Пройдено':n?`Частично, ${n} из ${total}`:'Не пройдено'}">${n===total?'✓':n?`${n}/${total}`:'·'}</b></div>`}).join('')}
function dailyTrainingHTML(){const day=dailyToday(),words=dailyWords(day),phrases=dailyPhrases(day),questions=dailyQuestions(day),answeredCount=dailyQuizCount(day,questions),wordDone=dailyWordsDone(day,words),phraseDone=dailyMarked(day,'phrases'),quizDone=!!questions.length&&answeredCount===questions.length,progress=Number(wordDone)+Number(phraseDone)+Number(quizDone)+Number(window.DailyListening.done(day));return `<div class="daily-head"><div><span class="tag">ТВОЯ ПРАКТИКА</span><h1>Моя тренировка на сегодня</h1><p class="sub">Слова, рабочие фразы, тест и аудирование · по шесть заданий</p></div><span class="daily-total">${progress}/4</span></div><progress aria-label="Прогресс тренировки" max="4" value="${progress}"></progress>${progress===4?'<div class="daily-complete" role="status">✓ На сегодня всё. Хорошая работа.</div>':''}<section class="panel daily-step"><div class="daily-step-title"><div><span class="tag">01 · 4–5 минут</span><h2>Сложные слова</h2></div><label class="daily-check"><input type="checkbox" disabled ${wordDone?'checked':''}> ${wordDone?'Повторил':(dailyTraining[day]?.viewedWords||[]).filter(id=>words.some(d=>d.id===id)).length+'/'+words.length+' просмотрено'}</label></div><p class="sub">Сначала вспомни перевод сам, затем открой подсказку. Сначала идут слова на повторение и ошибки в тестах.</p><div class="daily-words">${words.map(d=>`<button type="button" class="daily-word ${dailyTraining[day]?.viewedWords?.includes(d.id)?'viewed':''}" data-daily-word="${esc(d.id)}" aria-pressed="${!!dailyTraining[day]?.viewedWords?.includes(d.id)}"><span class="zh">${esc(d.zh)}</span>${dailyTraining[day]?.viewedWords?.includes(d.id)?`<span class="py">${esc(d.py)}</span><span>${esc(d.ru)}</span><small>✓ Просмотрено</small>`:'<small>Нажми, чтобы показать перевод</small>'}</button>`).join('')||'<p>Подходящих слов пока нет.</p>'}</div></section><section class="panel daily-step"><div class="daily-step-title"><div><span class="tag">02 · 3–5 минут</span><h2>Рабочие фразы</h2></div><label class="daily-check"><input type="checkbox" data-training-step="phrases" ${phraseDone?'checked':''}> Проговорил</label></div><p class="sub">Прочитай вслух, попробуй перевести, потом открой подсказку.</p><div class="daily-phrases">${phrases.map(p=>`<article class="daily-phrase"><div class="zh">${esc(p.zh)}</div><details><summary>Показать пиньинь и перевод</summary><div class="py">${esc(p.py)}</div><div>${esc(p.ru)}</div></details><small class="sub">${esc(p.topic)}</small></article>`).join('')||'<p>В базе пока нет подходящих рабочих примеров.</p>'}</div></section><section class="panel daily-step"><div class="daily-step-title"><div><span class="tag">03 · 2–5 минут</span><h2>Короткий тест</h2></div><label class="daily-check"><input type="checkbox" ${quizDone?'checked':''} disabled> ${quizDone?'Завершён':`${answeredCount}/${questions.length} ответов`}</label></div><p class="sub">Выбери иероглифы для русского значения.</p>${questions.map((q,i)=>{const answered=dailyAnswered(day,q.d.id);const result=dailyTraining[day]?.answers?.[q.d.id]?'1':dailyTraining[day]?.answers?.[q.d.id]===false?'0':'';return `<article class="daily-question"><div><b>${i+1}.</b> ${esc(q.d.ru)}</div><div class="daily-options">${q.options.map(d=>`<button data-daily-answer="${esc(q.d.id)}" data-daily-choice="${esc(d.id)}" ${answered?'disabled':''} class="${answered&&d.id===q.d.id?'good':''}">${esc(d.zh)}</button>`).join('')}</div>${answered?`<small class="${result==='1'?'ok':'bad'}">${result==='1'?'Верно':'Ответ записан. Правильно: '+esc(q.d.zh)}</small>`:''}</article>`}).join('')||'<p>В базе недостаточно слов для теста.</p>'}</section>${window.DailyListening.html(day)}<section class="panel daily-history"><div class="daily-step-title"><div><h2>Тренировки по дням</h2><p class="sub">Отметки сохраняются в аккаунте и видны на устройствах с синхронизацией.</p></div><strong>${progress===4?'Сегодня пройдено':progress?`Сегодня частично · ${progress} из 4`:'Сегодня не пройдено'}</strong></div><div class="daily-days">${dailyHistoryHTML(day)}</div><div class="daily-legend"><span>✓ Пройдено</span><span>Частично</span><span>· Не начато</span></div><button data-go="home">К общему прогрессу →</button></section>`}
const ACTIVE_TIME_KEY='chinese-workbench-active-time-v1',ACTIVE_SHARDS_KEY='chinese-active-time-shards-v2',ACTIVE_DEVICE_KEY='chinese-active-device-v2',ACTIVE_TAB_KEY='chinese-active-tab-v2';
let lastActiveAction=0,lastActiveDay='',activeTimeTimer;
function safeObject(key){try{const x=JSON.parse(localStorage.getItem(key)||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{}}catch{return {}}}
function activeDevice(){try{let id=localStorage.getItem(ACTIVE_DEVICE_KEY);if(!id){id=crypto.randomUUID();localStorage.setItem(ACTIVE_DEVICE_KEY,id)}return id}catch{return 'temporary'}}
function activeTab(){try{let id=sessionStorage.getItem(ACTIVE_TAB_KEY);if(!id){id=crypto.randomUUID();sessionStorage.setItem(ACTIVE_TAB_KEY,id)}return id}catch{return activeDevice()}}
function readActiveTimeShards(){const records=safeObject(ACTIVE_SHARDS_KEY);try{const marker=ACTIVE_DEVICE_KEY+'-migrated';if(!localStorage.getItem(marker)){const device=activeDevice();for(const [day,ms]of Object.entries(safeObject(ACTIVE_TIME_KEY)))if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&Number(ms)>0)records[day+':legacy-'+device]=Number(ms);localStorage.setItem(ACTIVE_SHARDS_KEY,JSON.stringify(records));localStorage.setItem(marker,'1')}}catch{}return records}
function mergeActiveTime(remote){const records=readActiveTimeShards();for(const [key,value]of Object.entries(remote))if(typeof value==='number'&&Number.isFinite(value)&&value>=0)records[key]=Math.max(Number(records[key])||0,value);try{localStorage.setItem(ACTIVE_SHARDS_KEY,JSON.stringify(records))}catch{}refreshActiveDisplay()}
function activeTimeText(ms){return `${Math.floor(Math.max(0,ms)/60000)} мин`}
function activeDayTotal(day,records=readActiveTimeShards()){return Object.entries(records).reduce((sum,[key,n])=>sum+(key.startsWith(day+':')&&Number.isFinite(Number(n))?Math.max(0,Number(n)):0),0)}
function activeToday(){return activeDayTotal(dailyToday())}
function activeChartHTML(){const records=readActiveTimeShards(),today=dailyToday(),days=Array.from({length:10},(_,i)=>{const date=new Date(`${today}T12:00:00`);date.setDate(date.getDate()-9+i);const key=date.toLocaleDateString('sv-SE'),ms=activeDayTotal(key,records),minutes=Math.floor(ms/60000);return {key,ms,minutes,label:date.toLocaleDateString('ru-RU',{day:'numeric',month:'short'}).replace('.',''),today:i===9}}),max=Math.max(1,...days.map(d=>d.ms));return `<div class="activity-chart" role="list" aria-label="Активное время за последние десять дней">${days.map(d=>{const amount=d.ms&&d.minutes===0?'&lt;1':String(d.minutes),height=d.ms?Math.max(4,d.ms/max*100):0,description=`${d.today?'Сегодня, ':''}${d.label}: ${d.ms&&d.minutes===0?'меньше минуты':d.minutes+' мин'}`;return `<div class="activity-day ${d.today?'is-today':''}" role="listitem" aria-label="${description}" title="${description}"><span class="activity-value">${amount}</span><div class="activity-track"><span class="activity-bar" style="height:${height}%"></span></div><span class="activity-date">${d.today?'Сегодня':d.label}</span></div>`}).join('')}</div>`}
function refreshActiveDisplay(){const el=document.querySelector('#activeTimeToday');if(el)el.textContent=activeTimeText(activeToday());const chart=document.querySelector('#activeTimeChart');if(chart){const html=activeChartHTML();if(chart.innerHTML!==html)chart.innerHTML=html}}
function recordActiveAction(){if(document.visibilityState!=='visible'||!document.hasFocus())return;const now=Date.now(),day=dailyToday(),gap=now-lastActiveAction;if(lastActiveAction&&lastActiveDay===day&&gap>0&&gap<=60000){const records=readActiveTimeShards(),key=day+':'+activeDevice()+':'+activeTab();records[key]=(Number(records[key])||0)+gap;try{localStorage.setItem(ACTIVE_SHARDS_KEY,JSON.stringify(records))}catch{}refreshActiveDisplay();clearTimeout(activeTimeTimer);activeTimeTimer=setTimeout(()=>{if(ready)persist()},1500)}lastActiveAction=now;lastActiveDay=day}
for(const event of ['pointerdown','keydown','wheel','touchmove'])document.addEventListener(event,recordActiveAction,{passive:true,capture:true});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'){lastActiveAction=0;if(ready)persist()}});window.addEventListener('blur',()=>{lastActiveAction=0});window.addEventListener('storage',e=>{if(e.key===ACTIVE_SHARDS_KEY)refreshActiveDisplay()});
function dashboardStats(){const remembered=data.filter(d=>d.state==='Изучено').length,seen=data.filter(d=>d.viewedAt||d.state==='Изучено'||d.state==='Повторить').length;return {remembered,seen,repeat:data.filter(d=>d.state==='Повторить').length,total:data.length}}
function dashboardHTML(){const s=dashboardStats(),pct=s.total?Math.round(s.remembered/s.total*1000)/10:0,day=new Date().toLocaleDateString('sv-SE'),today=data.filter(d=>d.viewedAt&&new Date(d.viewedAt).toLocaleDateString('sv-SE')===day).length;
const topics=WORK_TOPICS.map(t=>{const a=data.filter(d=>d.tags.includes(t));return {t,total:a.length,seen:a.filter(d=>d.viewedAt||d.state!=='Новое').length,known:a.filter(d=>d.state==='Изучено').length}}).filter(x=>x.total);
return `<h1>Мой прогресс</h1><p class="sub">Сегодня считаются все прохождения, а за всё время — уникальные карточки. Данные сохраняются в аккаунте при доступной синхронизации.</p><section class="panel daily-launch"><div><span class="tag">10–15 МИНУТ</span><h2>Моя тренировка на сегодня</h2><p class="sub">Сложные слова, рабочие фразы и короткий тест · сегодня ${dailyStatus(dailyToday())}/4 этапа</p></div><button class="primary" data-go="daily">${dailyStatus(dailyToday())?"Продолжить тренировку →":"Начать тренировку →"}</button></section><h2>Прогресс за сегодня</h2><div class="stats progress-stats today-stats"><div class="stat">Время на сайте<b id="activeTimeToday">${activeTimeText(activeToday())}</b><small>Активные минуты</small></div><div class="stat">Вопросов решено<b>${num(practiceToday().tests)}</b><small>Все ответы: верные и неверные</small></div><div class="stat">Карточек пройдено<b>${num(practiceToday().cards)}</b><small>«Помню» и «Не помню», включая повторения</small></div></div><p class="sub">Счётчики прохождений ведутся с этого обновления. Простое возвращение назад не добавляет прохождение.</p><h2>Прогресс за всё время</h2><div class="stats progress-stats total-stats"><div class="stat">Просмотрено<b>${num(s.seen)}</b><small>из ${num(s.total)} уникальных карточек</small></div><div class="stat">Помню<b>${num(s.remembered)}</b><small>Текущая отметка «Помню»</small></div><div class="stat">Нужно повторить<b>${num(s.repeat)}</b><small>«Не помню» и ошибки в тестах</small></div></div><section class="panel activity-panel"><div class="activity-heading"><div><span class="activity-eyebrow">ТВОЯ ПРАКТИКА</span><h2>Время на повторение</h2><p class="sub">Активные минуты за последние 10 дней · на всех устройствах</p></div><span class="activity-unit">МИНУТЫ</span></div><div id="activeTimeChart">${activeChartHTML()}</div><p class="activity-note">Учитывается время между действиями с паузой не больше минуты. 0 — записанной активности нет.</p></section><section class="panel" style="margin-top:20px"><h2>Помню ${pct}% базы</h2><progress aria-label="Доля слов с отметкой Помню" max="${s.total||1}" value="${s.remembered}"></progress><p class="sub">Без отметки «Помню»: ${num(s.total-s.remembered)}. В базе есть слова, фразы и конструкции.</p><div class="bar"><button data-go="cards" class="primary">Продолжить карточки →</button><button data-go="repeat">Разобрать повторение</button><button data-go="quiz">Тест по теме</button></div></section><p class="notice">Просмотр записывается, когда карточка видна на экране. Учёт просмотров начат 10 ноября 2026; прежние «Помню» и «Повторить» тоже учтены как просмотренные. Повторное открытие не увеличивает число. «Не помню» снимает отметку «Помню».</p><h2>Прогресс по рабочим темам</h2><div class="scrolltable"><table><thead><tr><th>Тема</th><th>Просмотрено</th><th>Помню</th><th>Всего</th></tr></thead><tbody>${topics.map(x=>`<tr><td>${esc(x.t)}</td><td>${num(x.seen)}</td><td>${num(x.known)}</td><td>${num(x.total)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Одно слово может входить в несколько тем; строки таблицы не суммируются.</p><h2>Наполнение примерами</h2><p>${num(data.filter(d=>d.examples.length).length)} карточек с примерами из ${num(s.total)}.</p>`}

let lessonCategory='Все';
function lessonsHTML(){const categories=['Все',...new Set((corpus.lessons||[]).map(x=>x.category))];setTimeout(()=>document.querySelectorAll('[data-lesson-category]').forEach(b=>b.onclick=()=>{lessonCategory=b.dataset.lessonCategory;render()}),0);return `<h1>Уроки 燕子</h1>${window.LessonNotes?.html()||''}<div class="topic-strip">${categories.map(c=>`<button data-lesson-category="${esc(c)}" class="${c===lessonCategory?'active':''}">${esc(c)}</button>`).join('')}</div><div class="bar"><button id="shuffleLessons">⤨ Перемешать</button><button id="lessonVocabulary">Словарь уроков</button><a href="${esc(corpus.lessonImport?.sourceUrl)}" target="_blank" rel="noopener">Открыть записи уроков</a></div><div class="grid">${shuffledViewItems((corpus.lessons||[]).filter(x=>lessonCategory==='Все'||x.category===lessonCategory),'lessons',x=>x.category+'\u0000'+x.title).map(x=>`<article class="item"><span class="tag">${esc(x.category)}</span><h2>${esc(x.title)}</h2><div class="zh">${esc(x.pattern)}</div><div class="py">${esc(x.patternPy)}</div><p>${esc(x.explanation)}</p>${exampleHTML(x)}</article>`).join('')}</div>`}

