const quoteDay=()=>new Date().toLocaleDateString('sv-SE');let activeQuoteDay=quoteDay();let quoteAt=Math.floor(Date.parse(activeQuoteDay+'T00:00:00Z')/86400000)%headerQuotes.length;try{const q=JSON.parse(localStorage.getItem('daily-header-quote')||'null');if(q?.day===activeQuoteDay&&Number.isInteger(q.index))quoteAt=q.index%headerQuotes.length}catch{}
