 const key='chinese-sidebar-order',collapsedKey='chinese-sidebar-collapsed';
 const buttons=()=>[...side.querySelectorAll(':scope > [data-nav]')];
 function saveOrder(){try{localStorage.setItem(key,JSON.stringify(buttons().map(b=>b.dataset.nav)))}catch{}}
